#!/usr/bin/env bash
# Writes the winget manifests of a firebrick release, for the wmeints.Firebrick package in microsoft/winget-pkgs.
#
# Usage: winget-manifests.sh <tag> <path to the .zip.sha256 file> <output directory>
#
# The .sha256 file is the firebrick-<tag>-x86_64-pc-windows-msvc.zip.sha256 file the release workflow's package
# job writes. The output directory gets the version, installer and en-US locale manifests.
set -euo pipefail

if [ $# -ne 3 ]; then
  echo "usage: $0 <tag> <path to the .zip.sha256 file> <output directory>" >&2
  exit 2
fi

tag=$1
sha_file=$2
out=$3

# Pre-releases such as v0.2.0-rc.1 don't go to winget.
if ! [[ $tag =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  echo "error: tag $tag doesn't look like v<major>.<minor>.<patch>" >&2
  exit 1
fi
version=${tag#v}

if [ ! -f "$sha_file" ]; then
  echo "error: $sha_file is missing" >&2
  exit 1
fi
read -r sum _ < "$sha_file" || true
if ! [[ ${sum:-} =~ ^[0-9a-fA-F]{64}$ ]]; then
  echo "error: $sha_file doesn't hold a sha256 checksum" >&2
  exit 1
fi
# winget writes and compares the checksum in uppercase.
sum=$(printf '%s' "$sum" | tr '[:lower:]' '[:upper:]')

id=wmeints.Firebrick
name=firebrick-$tag-x86_64-pc-windows-msvc
release=https://github.com/wmeints/firebrick/releases/tag/$tag
header="# Generated by .github/scripts/winget-manifests.sh in wmeints/firebrick; don't edit it by hand."

mkdir -p "$out"

cat > "$out/$id.yaml" <<EOF
$header
# yaml-language-server: \$schema=https://aka.ms/winget-manifest.version.1.10.0.schema.json
PackageIdentifier: $id
PackageVersion: $version
DefaultLocale: en-US
ManifestType: version
ManifestVersion: 1.10.0
EOF

# fbk starts the fbkd next to it or on the PATH, so both get a command alias.
cat > "$out/$id.installer.yaml" <<EOF
$header
# yaml-language-server: \$schema=https://aka.ms/winget-manifest.installer.1.10.0.schema.json
PackageIdentifier: $id
PackageVersion: $version
InstallerType: zip
NestedInstallerType: portable
NestedInstallerFiles:
  - RelativeFilePath: $name\\fbk.exe
    PortableCommandAlias: fbk
  - RelativeFilePath: $name\\fbkd.exe
    PortableCommandAlias: fbkd
Commands:
  - fbk
  - fbkd
Installers:
  - Architecture: x64
    InstallerUrl: https://github.com/wmeints/firebrick/releases/download/$tag/$name.zip
    InstallerSha256: $sum
ManifestType: installer
ManifestVersion: 1.10.0
EOF

cat > "$out/$id.locale.en-US.yaml" <<EOF
$header
# yaml-language-server: \$schema=https://aka.ms/winget-manifest.defaultLocale.1.10.0.schema.json
PackageIdentifier: $id
PackageVersion: $version
PackageLocale: en-US
Publisher: Willem Meints
PublisherUrl: https://github.com/wmeints
PublisherSupportUrl: https://github.com/wmeints/firebrick/issues
PackageName: Firebrick
PackageUrl: https://firebrick-sandbox.dev
License: MIT
LicenseUrl: https://github.com/wmeints/firebrick/blob/$tag/LICENSE
ShortDescription: Run coding agents in microVM sandboxes
Moniker: firebrick
Tags:
  - sandbox
  - microvm
  - coding-agent
ReleaseNotesUrl: $release
ManifestType: defaultLocale
ManifestVersion: 1.10.0
EOF
